import Foundation
import CoreVideo
import Testing
#if os(tvOS)
import TVVLCKit
#else
import MobileVLCKit
#endif
@testable import Dusk

@Suite("PGS rendering", .serialized)
@MainActor
struct PGSRenderingTests {
    @Test func embeddedPGSReachesRawVideoOutput() async throws {
        let fixture = Data(base64Encoded: Self.fixture)!
        let url = FileManager.default.temporaryDirectory.appendingPathComponent("pgs-render.mkv")
        try fixture.write(to: url)
        defer { try? FileManager.default.removeItem(at: url) }
        let library = VLCLibrary(options: [])
        let player = VLCMediaPlayer(library: library)
        let sink = PGSFrameSink()
        let output = DuskVLCRawVideoOutput(frameConsumer: sink)
        #expect(output.attach(to: player))
        player.media = VLCMedia(url: url)
        player.play()
        defer { player.stop(); output.detach() }
        var selected = false
        for _ in 0..<50 {
            try await Task.sleep(for: .milliseconds(100))
            if !selected, let id = (player.videoSubTitlesIndexes as? [NSNumber])?.first(where: { $0.intValue >= 0 }) {
                player.currentVideoSubTitleIndex = id.int32Value
                selected = true
            }
        }
        #expect(sink.counts.frames > 0)
        #expect(sink.counts.bright > 0)
    }
    // Synthetic 192×144 black H.264 clip with a white PGS rectangle at
    // 1–3, 4–6, and 7–9 seconds; no copyrighted media or Plex connection.
    // Scan the whole frame: VLC may pad/rescale the PGS canvas.
    private static let fixture = ""

}

private final class PGSFrameSink: NSObject, DuskVLCVideoFrameConsumer, @unchecked Sendable {
    private let lock = NSLock()
    private var frames = 0
    private var bright = 0
    var counts: (frames: Int, bright: Int) { lock.withLock { (frames, bright) } }
    func duskVLCVideoOutputDidProduce(_ buffer: CVPixelBuffer) {
        CVPixelBufferLockBaseAddress(buffer, .readOnly)
        defer { CVPixelBufferUnlockBaseAddress(buffer, .readOnly) }
        let pitch = CVPixelBufferGetBytesPerRow(buffer)
        let base = CVPixelBufferGetBaseAddress(buffer)!.assumingMemoryBound(to: UInt8.self)
        let value = (0..<CVPixelBufferGetHeight(buffer)).map { row in
            (0..<CVPixelBufferGetWidth(buffer)).map { base[row * pitch + $0 * 4] }.max() ?? 0
        }.max() ?? 0
        lock.withLock { frames += 1; if value > 128 { bright += 1 } }
    }
}
